  for (const n in zones.num) { const c = zones.num[n]; num[n] = { min: b64(c.min), max: b64(c.max), blank: b64(c.blank) }; }
  for (const n in zones.cat) { const c = zones.cat[n]; cat[n] = { dict: c.dict, bits: b64(c.bits) }; }
