    const cx = Math.floor((X - x0 + pad) / _CELL), cy = Math.floor((Y - y0 + pad) / _CELL);
    if (cx < 0 || cy < 0 || cx >= cols || cy >= rows) { cellOf[i] = -1; continue; }
    const c = cy * cols + cx;
